Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
using namespace std::chrono;
using ll = long long;
const ll INF = 1000000009;

struct Edge {
    int u, v, f, c;
    Edge(int u, int v, int f, int c) : u(u), v(v), f(f), c(c) {}
};

int src, snk;
vector<vector<int>> g;
vector<Edge> e;

void addEdge(int u, int v, int cap) {
    g[u].push_back(e.size());
    e.emplace_back(u, v, 0, cap);
    g[v].push_back(e.size());
    e.emplace_back(v, u, 0, 0);
}

int ptr[1001], d[1001];

bool bfs() {
    fill(d, d + 1001, -1);
    d[src] = 0;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : g[u]) {
            auto& ed = e[id];
            if (d[ed.v] == -1 && ed.f < ed.c) {
                d[ed.v] = d[u] + 1;
                q.push(ed.v);
                if (ed.v == snk) return true;
            }
        }
    }
    return false;
}

ll dfs(int u, ll f) {
    if (u == snk || f == 0) return f;
    for (int& i = ptr[u]; i < (int)g[u].size(); ++i) {
        int id = g[u][i];
        auto& ed = e[id];
        if (d[ed.v] != d[u] + 1) continue;
        ll pushed = dfs(ed.v, min(f, (ll)ed.c - ed.f));
        if (pushed) {
            ed.f += pushed;
            e[id ^ 1].f -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll maxFlow() {
    ll flow = 0;
    while (bfs()) {
        memset(ptr, 0, sizeof(ptr));
        ll pushed;
        while ((pushed = dfs(src, INF)) > 0)
            flow += pushed;
    }
    return flow;
}

string sci[101], rec[101];
bool ok[10][10][10][10];
int seen[101][101];
int badAt[10][10];
int R, C;

bool inRange(int r, int c) {
    return r >= 0 && c >= 0 && r < R && c < C;
}

int idx(int r, int c) {
    return 1 + C * r + c;
}

int main() {
    ios::sync_with_stdio(false);
    int T;
    cin >> R >> T;
    ++T;
    C = R;
    snk = C * C * 2 + 1;
    src = 0;
    g.resize(C * C * 2 + 2);
    queue<pair<int, int>> q;
    for (int i = 0; i < R; ++i) cin >> sci[i];
    for (int i = 0; i < R; ++i) {
        cin >> rec[i];
        for (int j = 0; j < C; ++j) {
            badAt[i][j] = INF;
            if (rec[i][j] == 'Z') {
                q.push({i, j});
                badAt[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (inRange(nx, ny) && badAt[nx][ny] == INF && sci[nx][ny] != 'Y') {
                        badAt[nx][ny] = badAt[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < R; ++x)
        for (int y = 0; y < C; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                addEdge(src, idx(x, y), sci[x][y] - '0');
            if (rec[x][y] >= '1' && rec[x][y] <= '9')
                addEdge(R * R + idx(x, y), snk, rec[x][y] - '0');
            for (int X = 0; X < R; ++X)
                for (int Y = 0; Y < C; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' ||
                        rec[X][Y] == 'Y' || rec[X][Y] == 'Z')
                        continue;
                    memset(seen, 0, sizeof(seen));
                    queue<tuple<int, int, int>> bq;
                    bq.emplace(x, y, 1);
                    seen[x][y] = 1;
                    while (!bq.empty()) {
                        auto [cx, cy, t] = bq.front(); bq.pop();
                        if (cx == X && cy == Y) {
                            seen[cx][cy] = 1;
                            break;
                        }
                        if (t >= badAt[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (inRange(nx, ny) && !seen[nx][ny] &&
                                        sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' &&
                                        t + 1 <= badAt[nx][ny]) {
                                        seen[nx][ny] = 1;
                                        bq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (seen[X][Y])
                        addEdge(idx(x, y), R * R + idx(X, Y), INF);
                }
        }
    cout << maxFlow() << '\n';
}
